import {OFFICIAL_MAINTENANCE_JA as unversionedMaintenanceCatalog} from './official-maintenance-ja.js';
const l=s=>s.split('|');
export const SERVICE_CATEGORIES=[l('清掃・注油|Cleaning & lubrication|Čištění a mazání|Reinigung & Schmierung'),l('ノズル・ホットエンド|Nozzle & hotend|Tryska a hotend|Düse & Hotend'),l('調整・部品交換|Adjustment & replacement|Seřízení a výměny|Einstellung & Austausch')];
export const SERVICE_SOURCES={regular:'https://help.prusa3d.com/article/regular-printer-maintenance-core-one_829710',belt:'https://help.prusa3d.com/article/adjusting-belt-tension-core-one-core-one-indx-core-one-l_845048',sheet:'https://help.prusa3d.com/article/flexible-steel-sheets-guidepost_2195',hotend:'https://help.prusa3d.com/guide/how-to-replace-a-hotend-assembly-core-one_385707',nozzle:'https://help.prusa3d.com/guide/how-to-replace-the-prusa-nozzle-core-one_821168'};
const step=(title,body,refs,extra={})=>({title:l(title),body:l(body),refs,...extra});
const routine=(id,title,interval,refs,body,extra={})=>({id,title:l(title),category:0,interval:l(interval),source:SERVICE_SOURCES.regular,steps:[step(title,body,refs,extra)]});
const everyPrint='印刷前|Before printing|Před tiskem|Vor dem Druck',hours='200時間ごとに点検|Inspect every 200 h|Kontrola každých 200 h|Alle 200 h prüfen';
export const SERVICE_TASKS=[
 routine('debris','本体内の清掃|Clear loose debris|Odstranění nečistot|Lose Rückstände entfernen',everyPrint,['base','heatbed'],'冷却後、ベッドの下などに残ったフィラメント片やほこりを取り除きます。|Once cool, remove loose filament and dust, including beneath the bed.|Po vychladnutí odstraňte úlomky filamentu a prach, také pod podložkou.|Nach dem Abkühlen Filamentreste und Staub auch unter dem Heizbett entfernen.'),
 routine('panels','パネルの清掃|Clean panels|Čištění panelů|Paneele reinigen',everyPrint,['door','windowRight'],'アルコールを含まない洗剤か石けん水を使います。IPAなどのアルコール製品は使いません。|Use alcohol-free cleaner or soapy water. Do not use IPA or other alcohol products.|Použijte čistič bez alkoholu nebo mýdlovou vodu. Nepoužívejte IPA ani jiné alkoholové přípravky.|Alkoholfreien Reiniger oder Seifenwasser verwenden. Kein IPA und keine anderen Alkoholprodukte.'),
 {...routine('sheet','スチールシートの手入れ|Care for the print sheet|Péče o tiskový plát|Druckplatte pflegen',everyPrint,['sheet'],'ベッドとシートが冷えてから清掃します。スムースPEI・サテン・テクスチャーは、約90%のIPAを無香料のペーパータオルに付けて印刷面を拭きます。皮膚用のアルコール製品は使いません。\n\nPA Nylonは水で清掃し、油分は食器用洗剤で落とします。IPA・アセトンなどのアルコールや溶剤は使いません。\n\nサテン・テクスチャーにアセトンは使いません。別の種類は、対応する公式シートの手入れ方法を確認してください。\n\n清掃後は、シートと材料の組合せに合う表面準備も必要です。スムースPEIでPETGなど密着の強い材料を使う場合は、公式材料表で分離層の要否を確認し、必要ならスティックのり等を薄く塗ります。TPU/TPEをスムースPEIまたはサテンで印刷するときは分離層を設け、取り外す際の表面損傷を防ぎます。|Clean only after the bed and sheet are cold. For smooth PEI, satin and textured sheets, wipe the print surface with an unscented paper towel moistened with about 90% IPA. Do not use skin-care alcohol products.\n\nFor PA Nylon, clean with water and degrease with dish-washing soap. Do not use IPA, acetone or other alcohol-based solvents.\n\nNever use acetone on satin or textured sheets. For other sheet types, follow the corresponding official care instructions.\n\nAfter cleaning, prepare the surface for the sheet and filament combination. For PETG and other strongly adhering materials on smooth PEI, check the official material table and apply a thin separation layer when required. For TPU/TPE on smooth or satin sheets, use a separation layer such as glue stick to prevent surface damage during removal.|Čistěte až po vychladnutí podložky a plátu. Hladké PEI, saténové a zrnité pláty otřete neparfémovanou papírovou utěrkou navlhčenou přibližně 90% IPA. Nepoužívejte alkoholové přípravky na pokožku.\n\nPA Nylon čistěte vodou a odmašťujte prostředkem na mytí nádobí. Nepoužívejte IPA, aceton ani jiné alkoholové čističe.\n\nNa saténové ani zrnité pláty nikdy nepoužívejte aceton. U jiného typu plátu postupujte podle příslušného oficiálního návodu.\n\nPo vyčištění připravte povrch také podle kombinace plátu a filamentu. Pro PETG a další silně přilnavé materiály na hladkém PEI ověřte v oficiální tabulce materiálů, zda je potřebná tenká separační vrstva. Pro TPU/TPE na hladkém nebo saténovém plátu použijte separační vrstvu, například lepidlo v tyčince, aby se při sejmutí nepoškodil povrch.|Erst reinigen, wenn Heizbett und Platte kalt sind. Glatte PEI-, Satin- und texturierte Platten mit einem unparfümierten Papiertuch und etwa 90% IPA abwischen. Keine alkoholhaltigen Hautpflegeprodukte verwenden.\n\nPA Nylon mit Wasser reinigen und mit Spülmittel entfetten. Kein IPA, Aceton oder andere alkoholhaltige Reiniger verwenden.\n\nSatin- und texturierte Platten nie mit Aceton reinigen. Für andere Plattentypen die jeweilige offizielle Pflegeanleitung beachten.\n\nNach der Reinigung die Oberfläche auch auf die Kombination aus Platte und Filament abstimmen. Bei PETG und anderen stark haftenden Materialien auf glattem PEI die offizielle Materialtabelle prüfen und bei Bedarf eine dünne Trennschicht auftragen. Bei TPU/TPE auf glatten oder Satinplatten eine Trennschicht wie Klebestift verwenden, um Schäden beim Ablösen zu vermeiden.'),source:SERVICE_SOURCES.sheet,revision:2},
 routine('rod','Y軸ロッドの清掃・注油|Clean and lubricate Y rods|Čištění a mazání tyčí Y|Y-Stangen reinigen und schmieren',hours,[377,566],'ロッドを紙タオルで清掃し、Prusa Lubricantを少量塗ります。|Wipe the rods and apply a little Prusa Lubricant.|Tyče otřete a naneste malé množství Prusa Lubricant.|Stangen abwischen und wenig Prusa Lubricant auftragen.'),
 routine('rail','X軸レールの手入れ|Care for the X rail|Údržba kolejnice X|X-Schiene pflegen','200時間点検・注油は3〜6か月|Inspect at 200 h; lubricate at 3–6 months|Kontrola po 200 h; mazání po 3–6 měsících|Nach 200 h prüfen; alle 3–6 Monate schmieren',[382],'乾いた布で清掃し、注油には専用レール注油セットを使います。Prusa Lubricant・脱脂剤は使いません。|Wipe dry. Use the dedicated rail lubrication set; no Prusa Lubricant or degreaser.|Otřete nasucho. Použijte sadu pro mazání kolejnic, ne Prusa Lubricant ani odmašťovač.|Trocken abwischen. Das spezielle Schienenschmierset verwenden, kein Prusa Lubricant oder Entfetter.'),
 routine('fans','ファンの清掃|Clean fans|Čištění ventilátorů|Lüfter reinigen','数百時間ごと|Every few hundred hours|Každých několik set hodin|Alle paar hundert Stunden',[834,791],'電源を切り、電源コードを抜いてから、ほこりや糸状の樹脂を取り除きます。回転中にエアを吹きません。|Switch off and unplug before removing dust and strands. Do not blow air onto a running fan.|Před odstraněním prachu a vláken vypněte tiskárnu a odpojte napájení. Na běžící ventilátor nefoukejte vzduch.|Vor dem Entfernen von Staub und Fäden ausschalten und Netzstecker ziehen. Laufende Lüfter nicht anblasen.'),
 routine('extruder','送りギアの清掃|Clean the drive gear|Čištění podávacího kola|Antriebsrad reinigen',hours,['pgAssembly','idlerBearing1','idlerBearing2'],'アイドラーを開き、付着した樹脂を除きます。送りギアとアイドラーベアリングには注油しません。PGアダプターなしでギアボックスを開けません。|Open the idler and remove debris. Do not lubricate the drive gear or idler bearings. Do not open the gearbox without its PG adapter.|Otevřete idler a odstraňte nečistoty. Podávací kolo ani ložiska idleru nemažte. Převodovku neotvírejte bez PG adaptéru.|Idler öffnen und Rückstände entfernen. Antriebsrad und Idlerlager nicht schmieren. Getriebe nicht ohne PG-Adapter öffnen.',{transparent:[790,794,816]}),
 routine('electronics','電装の点検|Inspect electrical connections|Kontrola elektrických spojů|Elektrische Verbindungen prüfen','600〜800時間・年次点検|600–800 h / annual inspection|600–800 h / roční kontrola|600–800 h / jährliche Prüfung',['xBuddy','xBuddyExtension'],'電源を切り、電源コードを抜いてから接続を点検します。ラッチのある端子は押してから抜きます。|Switch off and unplug before inspecting connections. Release connector latches before unplugging them.|Před kontrolou vypněte napájení a odpojte přívod. Před vytažením konektoru uvolněte západku.|Vor der Prüfung ausschalten und Netzstecker ziehen. Vor dem Abziehen die Steckerverriegelung lösen.',{camera:'back',transparent:[206]}),
 {id:'hotend-clean',title:l('ノズル外側の清掃|Clean the nozzle exterior|Čištění vnějšku trysky|Düsenaußenseite reinigen'),category:0,interval:l(everyPrint),source:SERVICE_SOURCES.regular,steps:[
  step('ノズルを温める|Warm the nozzle|Nahřátí trysky|Düse aufheizen','250 °Cで3〜5分温めます。高温部には触れません。|Heat to 250 °C for 3–5 minutes. Do not touch hot parts.|Nahřívejte na 250 °C po dobu 3–5 minut. Nedotýkejte se horkých částí.|3–5 Minuten auf 250 °C aufheizen. Heiße Teile nicht berühren.',['hotend'],{firmwareActions:["heat"]}),
  step('付着した樹脂を除く|Remove plastic residue|Odstranění zbytků plastu|Kunststoffreste entfernen','真鍮ブラシで清掃します。ヒーター・センサー配線にブラシを触れさせないでください。|Brush with brass bristles, avoiding heater and sensor wires.|Čistěte mosazným kartáčkem mimo vodiče topení a senzoru.|Mit einer Messingbürste reinigen; Heizungs- und Sensorkabel aussparen.',['hotend']),
  step('加熱を止め、室温まで冷ます|Stop heating and cool to room temperature|Vypnutí ohřevu a vychladnutí|Heizung abschalten und abkühlen','COOLDOWNを選んで加熱を止め、表示温度が室温まで下がるのを待ちます。約10分かかります。冷却を確認するまで高温部に触れません。|Select COOLDOWN to stop heating. Wait for the display to show ambient temperature, about 10 minutes. Do not touch hot parts before they have cooled.|Zvolte COOLDOWN a vypněte ohřev. Počkejte, až displej ukáže pokojovou teplotu, přibližně 10 minut. Do vychladnutí se horkých dílů nedotýkejte.|Mit COOLDOWN die Heizung abschalten. Warten, bis das Display Raumtemperatur zeigt, etwa 10 Minuten. Heiße Teile erst nach dem Abkühlen berühren.',['lcd'],{firmwareActions:["cooldown"]})]},
 {id:'belts',title:l('ベルトの張りを調整する|Adjust belt tension|Seřízení napnutí řemenů|Riemenspannung einstellen'),category:2,interval:l('張り・位置ずれを点検するとき|When inspecting tension or alignment|Při kontrole napnutí či souososti|Bei Prüfung von Spannung oder Ausrichtung'),source:SERVICE_SOURCES.belt,steps:[
  step('モーターを無効にする|Disable the motors|Vypnutí motorů|Motoren deaktivieren','CORE One／One+のキットは、組立時に左右テンショナーのM3×30ねじ2本の先端へPrusa Lubricantを少量塗ったか確認します。完成品や組立時に実施済みのキットは、追加塗布不要です。\n\n電源を切るか、LCDのControl → Disable Motorsを選びます。|For a CORE One/One+ kit, check whether a little Prusa Lubricant was applied to the tips of both M3x30 tensioner screws during assembly. Factory-assembled printers and kits already lubricated at assembly need no additional application.\n\nSwitch off, or select Control → Disable Motors.|U stavebnice CORE One/One+ ověřte, zda se při montáži naneslo malé množství Prusa Lubricant na špičky obou napínacích šroubů M3x30. Továrně sestavené tiskárny ani již promazané stavebnice další mazání nepotřebují.\n\nVypněte tiskárnu nebo zvolte Control → Disable Motors.|Bei einem CORE One/One+ Bausatz prüfen, ob die Spitzen beider M3x30-Spannschrauben bei der Montage mit etwas Prusa Lubricant geschmiert wurden. Bei fertig montierten Druckern und bereits bei der Montage geschmierten Bausätzen ist kein erneutes Schmieren nötig.\n\nAusschalten oder Control → Disable Motors wählen.',['lcd'],{firmwareActions:["disable"]}),
  step('ガントリーを前へ寄せる|Move the gantry forward|Posunutí portálu dopředu|Gantry nach vorne bewegen','NextruderをX中央・Y最前部へ動かし、左右の角を前枠に当ててがたつきを確認します。|Place the head at X centre and Y front; check both gantry corners against the frame for play.|Umístěte hlavu doprostřed X a dopředu Y; zkontrolujte vůli obou rohů portálu u rámu.|Druckkopf in X mittig und in Y ganz nach vorne schieben; beide Gantry-Ecken am Rahmen auf Spiel prüfen.',['gantry',377,566]),
  step('Belt Tunerで測る|Measure with Belt Tuner|Měření pomocí Belt Tuner|Mit Belt Tuner messen','公式Belt TunerでCORE One・XY-beltを選び、ベルト中央を弾いて測ります。|Choose CORE One and XY-belt in the official tuner; pluck the belt midpoint.|V oficiálním ladiči zvolte CORE One a XY-belt; brnkněte uprostřed řemenu.|Im offiziellen Tuner CORE One und XY-belt wählen; die Riemenmitte anzupfen.',[405,568,396,397],{link:'https://belt.connect.prusa3d.com/'}),
  step('少しずつ調整し、再測定する|Adjust gradually and remeasure|Postupné seřízení a nové měření|Schrittweise einstellen und erneut messen','CORE One/+の目安は上側98 Hz・下側92 Hzです。左右の位置合わせを保ち、公式説明に従って調整と測定を繰り返します。|For CORE One/+, aim for upper 98 Hz and lower 92 Hz. Preserve alignment and repeat adjustment and measurement as instructed.|Pro CORE One/+ je cílem nahoře 98 Hz a dole 92 Hz. Zachovejte souosost a opakujte seřízení i měření podle návodu.|Bei CORE One/+ oben 98 Hz und unten 92 Hz anstreben. Ausrichtung beibehalten und nach Anleitung erneut einstellen und messen.',[396,397,405,568],{camera:'front'})]}
];
SERVICE_CATEGORIES.push(l('初期設定|Initial setup|První nastavení|Ersteinrichtung'));
SERVICE_TASKS.push(INITIAL_SETUP_TASK);

const common=[
 step('交換方法を確認する|Review the replacement method|Kontrola postupu výměny|Austauschverfahren prüfen','標準Nextruderホットエンド用です。HT Hotend・V6アダプターは専用ガイドを使います。|For the standard Nextruder hotend. Use dedicated guides for HT Hotend or a V6 adapter.|Pro standardní hotend Nextruder. Pro HT Hotend a adaptér V6 použijte jejich návody.|Für den Standard-Nextruder-Hotend. Für HT Hotend oder V6-Adapter die jeweilige Anleitung nutzen.',['hotend']),
 step('工具を用意する|Prepare tools|Příprava nástrojů|Werkzeuge bereitlegen','六角レンチ2.5 mmを用意します。初期型カバーにはT10も必要です。ノズル単体の交換では13–16レンチと7 mm切り欠きのあるユニバーサルレンチを使います。締付け用には1.5 Nmを設定できるトルクレンチが推奨されています。|Prepare a 2.5 mm hex key and T10 for early covers. Nozzle-only replacement also needs a 13–16 wrench and the universal wrench with a 7 mm cutout. A torque wrench set to 1.5 Nm is recommended.|Připravte 2,5mm imbus a pro rané kryty T10. Samotná výměna trysky vyžaduje klíč 13–16 a univerzální klíč se 7mm výřezem. Doporučen je momentový klíč nastavený na 1,5 Nm.|2,5-mm-Innensechskant und für frühe Abdeckungen T10 bereitlegen. Für den Düsenwechsel auch 13–16-Schlüssel und Universalschlüssel mit 7-mm-Ausschnitt verwenden. Ein auf 1,5 Nm eingestellter Drehmomentschlüssel wird empfohlen.',['hotend']),
 step('フィラメントを抜き、冷却する|Unload and cool down|Vyjmutí filamentu a chlazení|Entladen und abkühlen','ドアを閉じてアンロードし、スプールを外します。COOLDOWNで室温まで冷まします。|Close the door, unload, remove the spool and cool to ambient.|Zavřete dveře, vysuňte filament, sejměte cívku a nechte vychladnout.|Tür schließen, Filament entladen, Spule entfernen und auf Raumtemperatur abkühlen.',['lcd'],{firmwareActions:["unload","cooldown"]}),
 step('ベッドを下げ、電源を外す|Lower the bed and unplug|Snížení podložky a odpojení|Heizbett absenken und Netzstecker ziehen','Control → Move Axis → Move Zを100 mm以上にします。ベッドが下がって停止してから背面スイッチを切り、電源コードを抜きます。|Set Control → Move Axis → Move Z to at least 100 mm. Wait for the bed to stop, then switch off at the rear and unplug.|Nastavte Control → Move Axis → Move Z alespoň na 100 mm. Počkejte na zastavení podložky, pak vypněte zadní vypínač a odpojte napájení.|Control → Move Axis → Move Z auf mindestens 100 mm stellen. Stillstand des Heizbetts abwarten, dann hinten ausschalten und Netzstecker ziehen.',['heatbed','psu'],{firmwareActions:["moveZ"]}),
 step('トップカバーを外す|Remove the top cover|Sejmutí horního krytu|Obere Abdeckung abnehmen','内側からナイロンリベットを押し出し、カバーを外します。|Release the nylon rivets from inside and lift off the cover.|Zevnitř uvolněte nylonové nýty a sejměte kryt.|Nylonnieten von innen lösen und Abdeckung abheben.',['top'],{action:'top-out'}),
 step('ベッドを保護する|Protect the bed|Ochrana podložky|Heizbett schützen','厚みのある布などでベッドを覆います。|Cover the bed with protective fabric.|Podložku překryjte ochrannou látkou.|Heizbett mit schützendem Stoff abdecken.',['heatbed']),
 step('左カバーを外す|Remove the left cover|Sejmutí levého krytu|Linke Abdeckung abnehmen','上側のM3x10を2.5 mm六角レンチで外し、左カバーを外します。初期型はM3x10bTが2本の場合があるため、T10で両方を外します。実機のネジを公式写真と照合してください。|Remove the upper M3x10 with a 2.5 mm hex key, then the left cover. Early printers may have two M3x10bT screws; remove both with T10. Match the actual screws to the official photos.|Vyjměte horní M3x10 pomocí 2,5mm imbusu a sejměte levý kryt. Rané tiskárny mohou mít dva M3x10bT; oba vyjměte pomocí T10. Šrouby porovnejte s oficiálními fotografiemi.|Obere M3x10 mit 2,5-mm-Innensechskant lösen und linke Abdeckung abnehmen. Frühe Drucker können zwei M3x10bT haben; beide mit T10 entfernen. Schrauben mit den offiziellen Fotos vergleichen.',[858],{action:'cover-out'}),
 step('ヒーターとサーミスターを抜く|Disconnect heater and thermistor|Odpojení topení a termistoru|Heizung und Thermistor abstecken','ラッチを押して、ヒーター、サーミスターの順に抜きます。|Release latches; disconnect heater, then thermistor.|Uvolněte západky; odpojte topení a potom termistor.|Verriegelungen lösen; zuerst Heizung, dann Thermistor abstecken.',['loveBoard',857],{action:'unplug'}),
 step('ホットエンドを引き抜く|Withdraw the hotend|Vyjmutí hotendu|Hotend herausziehen','ケーブルをガイドから外します。落下しないようホットエンドを片手で支え、もう片方の手でつまみネジ2本を数回転緩めます。ネジは抜き切りません。ホットエンドを下へ引き抜きます。|Free the cables from the guide. Hold the hotend to prevent it falling; loosen both thumbscrews a few turns with the other hand. Leave the screws in place and withdraw the hotend downward.|Uvolněte kabely z vedení. Hotend držte proti pádu a druhou rukou povolte oba ruční šrouby o několik otáček. Šrouby nevyjímejte; hotend vytáhněte dolů.|Kabel aus der Führung nehmen. Hotend gegen Herabfallen halten und beide Rändelschrauben mit der anderen Hand einige Umdrehungen lösen. Schrauben nicht ganz herausdrehen; Hotend nach unten herausziehen.',['hotend',795,807],{action:'hotend-out'})
];
const beltTask=SERVICE_TASKS.find(t=>t.id==='belts');
beltTask.revision=3;
beltTask.steps[2].title=l('Belt Tunerでマイク測定する|Measure with the microphone Belt Tuner|Měření mikrofonem v Belt Tuner|Mit dem Mikrofon-Belt-Tuner messen');
beltTask.steps[2].body=l('整列を確認したら、モーターを無効にした状態でNextruderをX右端・Y最前部へ動かします。公式Belt TunerでCORE One → XY-beltを選び、Start listeningを押します。端末をベルトに近づけ、上側・下側の中央をそれぞれ弾いて測ります。実機のManual Belt Tuningは別の測定方法です。|After alignment, with motors disabled, move the Nextruder fully right in X and forward in Y. In the official Belt Tuner select CORE One → XY-belt, then Start listening. Hold the device near each belt and pluck its midpoint. The printer’s Manual Belt Tuning uses a different method.|Po vyrovnání a s vypnutými motory posuňte Nextruder zcela doprava v X a dopředu v Y. V oficiálním Belt Tuner zvolte CORE One → XY-belt a Start listening. Přibližte zařízení k řemenu a brnkněte uprostřed horního i dolního řemenu. Manual Belt Tuning v tiskárně používá jinou metodu.|Nach dem Ausrichten bei deaktivierten Motoren den Nextruder in X ganz nach rechts und in Y ganz nach vorne schieben. Im offiziellen Belt Tuner CORE One → XY-belt und Start listening wählen. Gerät nahe an den jeweiligen Riemen halten und dessen Mitte anzupfen. Manual Belt Tuning am Drucker nutzt ein anderes Verfahren.');
beltTask.steps[3].body=l('マイク測定の目安は上側98 Hz・下側92 Hzです。両方のテンショナーネジを交互に同じ量ずつ、1回につき半回転調整して再測定します。左ネジは上側、右ネジは下側に作用します。前側の角に隙間が生じたら両ネジを緩め、整列からやり直します。実機のManual Belt Tuningでは、その画面と公式説明に従います。\n\n初期のCORE Oneキットで組立時の潤滑が未実施だった場合、他の対処でも改善しなければ無理に調整を続けません。左右のテンショナーや付属プーリーの交換が必要な場合があります。「手順と写真」の出典欄にある公式交換ガイドを確認してください。|For microphone measurement, aim for upper 98 Hz and lower 92 Hz. Adjust both tensioner screws evenly and alternately, half a turn at a time, then remeasure. The left screw controls the upper belt, the right the lower. If a front corner develops a gap, loosen both and realign. For Manual Belt Tuning, follow its screen and official guide.\n\nIf an early CORE One kit was not lubricated at assembly and the other measures have not helped, do not force further screw adjustment. The left/right tensioners or their pulleys may need replacement. See the official replacement guides under sources in Instructions & photos.|Při měření mikrofonem je cílem nahoře 98 Hz a dole 92 Hz. Oba napínací šrouby upravujte střídavě a stejně, vždy o půl otáčky, pak znovu měřte. Levý šroub ovládá horní řemen, pravý dolní. Objeví-li se vpředu mezera, oba povolte a znovu vyrovnejte. Při Manual Belt Tuning se řiďte displejem a oficiálním návodem.\n\nPokud raná stavebnice CORE One nebyla při montáži promazána a ostatní opatření nepomohla, šrouby dál neseřizujte silou. Může být nutná výměna levého či pravého napínáku nebo jejich kladek. Oficiální návody k výměně jsou ve zdrojích v části Postup a fotografie.|Bei Mikrofonmessung oben 98 Hz und unten 92 Hz anstreben. Beide Spannschrauben abwechselnd und gleichmäßig um jeweils eine halbe Umdrehung verstellen, dann erneut messen. Links wirkt auf den oberen, rechts auf den unteren Riemen. Entsteht vorne ein Spalt, beide lösen und neu ausrichten. Bei Manual Belt Tuning der Anzeige und offiziellen Anleitung folgen.\n\nWurde ein früher CORE One Bausatz bei der Montage nicht geschmiert und helfen die anderen Maßnahmen nicht, die Schrauben nicht mit Gewalt weiter verstellen. Eventuell müssen die linken/rechten Riemenspanner oder deren Rollen ersetzt werden. Die offiziellen Austausch-Anleitungen stehen unter den Quellen in Anleitung und Fotos.');
beltTask.steps[3].supplementalSources=[{"label":["左テンショナーの公式交換ガイド","Official left tensioner replacement guide","Oficiální návod k výměně levého napínáku","Offizielle Anleitung: linken Riemenspanner ersetzen"],"url":"https://help.prusa3d.com/guide/how-to-replace-the-belt-tensioner-left-core-one_948782"},{"label":["右テンショナーの公式交換ガイド","Official right tensioner replacement guide","Oficiální návod k výměně pravého napínáku","Offizielle Anleitung: rechten Riemenspanner ersetzen"],"url":"https://help.prusa3d.com/guide/how-to-replace-the-belt-tensioner-right-core-one_948790"},{"label":["テンショナープーリーの公式交換ガイド","Official tensioner pulley replacement guide","Oficiální návod k výměně kladky napínáku","Offizielle Anleitung: Riemenspannrolle ersetzen"],"url":"https://help.prusa3d.com/guide/how-to-replace-the-belt-tensioner-pulley-core-one_948766"}];
const tail=[
 step('ホットエンドを用意する|Prepare the hotend|Příprava hotendu|Hotend bereitlegen','組み上がったホットエンドを1個用意します。ノズルだけを交換した場合は、今組み直したものを使います。公式ガイドの標準ノズルは0.4 mm HF（CHT）です。装着するノズルの径・流量と、シリコンソックの有無を確認してください。交換後は「ノズル設定を合わせる」で同じ内容を設定します。|Prepare one complete hotend assembly. If you changed only the nozzle, use the assembly you just rebuilt. The official guide specifies a 0.4 mm HF (CHT) nozzle as standard. Check the fitted nozzle diameter and flow type, and whether the silicone sock is fitted. Match these choices in Update nozzle settings after reassembly.|Připravte jeden sestavený hotend. Pokud jste měnili pouze trysku, použijte právě sestavený hotend. Oficiální návod uvádí jako standard trysku 0,4 mm HF (CHT). Zkontrolujte průměr a průtokový typ namontované trysky a přítomnost silikonového návleku. Po montáži stejné údaje zadejte v kroku Nastavení trysky.|Ein vollständiges Hotend bereitlegen. Wurde nur die Düse gewechselt, das gerade wieder zusammengebaute Hotend verwenden. Die offizielle Anleitung nennt eine 0,4-mm-HF-Düse (CHT) als Standard. Durchmesser und Durchflusstyp der eingebauten Düse sowie die Silikonsocke prüfen. Nach dem Einbau diese Angaben im Schritt Düseneinstellungen anpassen übernehmen.',['hotend']),
 step('奥まで押し込み、固定する|Insert fully and secure|Úplné zasunutí a upevnění|Ganz einschieben und sichern','ケーブルを少し前へ向け、下からヒートシンクの奥まで差します。ホットエンド一式がファンシュラウドのくぼみに適切な隙間を残して収まり、その下へ突き出さないことを公式写真で確認します。上へ押し続けながら両方のつまみネジを締めます。|Angle the cables slightly forward and insert fully into the heatsink from below. Match the photo: the assembly must fit the fan-shroud recess with clearance and must not protrude below the shroud. Keep pushing upward while tightening both thumbscrews.|Kabely natočte mírně dopředu a hotend zasuňte zespodu nadoraz do chladiče. Podle fotografie ověřte usazení ve vybrání krytu ventilátoru s vůlí, bez vyčnívání pod kryt. Při utahování obou ručních šroubů tlačte vzhůru.|Kabel leicht nach vorne richten und Hotend von unten ganz in den Kühlkörper einschieben. Mit dem Foto vergleichen: Die Baugruppe muss mit Spiel in der Aussparung des Lüfterkanals sitzen und darf nicht darunter hervorstehen. Beim Anziehen beider Rändelschrauben weiter nach oben drücken.',['hotend',795,807],{action:'hotend-in'}),
 step('挿入位置を確認する|Check seating|Kontrola usazení|Sitz prüfen','銅色のリングが見えない位置まで入っているか、公式接写写真で確認します。|Check the official close-up: the copper ring must be concealed.|Podle oficiálního detailu ověřte, že měděný kroužek není vidět.|Am offiziellen Detailfoto prüfen: Der Kupferring darf nicht sichtbar sein.',['hotend',794]),
 step('ケーブルをガイドへ戻す|Route the cables|Vedení kabelů|Kabel führen','つまみネジの後ろにある樹脂フックの溝へ、サーミスター、ヒーターの順に通します。|Use the channel in the plastic hook behind the thumbscrews: thermistor cable first, then heater cable.|Do drážky plastového háčku za ručními šrouby veďte nejprve kabel termistoru, potom topení.|In der Nut des Kunststoffhakens hinter den Rändelschrauben zuerst das Thermistorkabel, dann das Heizkabel führen.',[857,'hotend'],{action:'route-hotend'}),
 step('LoveBoardへ接続する|Reconnect to LoveBoard|Připojení k LoveBoard|Wieder mit LoveBoard verbinden','サーミスターをLoveBoard左側の一番上のNT端子へ、次にヒーターを基板上部の黒いHEATER端子へ接続します。公式写真と基板表示を照合してください。|Connect the thermistor to NT at the top left of LoveBoard, then the heater to the black HEATER socket at the top. Match the official photo and board labels.|Připojte termistor do NT vlevo nahoře na LoveBoard, potom topení do černého HEATER nahoře. Ověřte podle oficiální fotografie a popisků desky.|Thermistor an NT oben links am LoveBoard anschließen, dann Heizung an die schwarze HEATER-Buchse oben. Mit offiziellem Foto und Platinenbeschriftung abgleichen.',['loveBoard'],{action:'plug'}),
 step('左カバーを戻す|Refit the left cover|Nasazení levého krytu|Linke Abdeckung montieren','下側を先に掛けて押し込み、M3x10で固定します。ベッドの保護材も外します。|Hook the bottom, close and fasten with M3x10. Remove bed protection.|Zahákněte spodní část, zavřete a upevněte M3x10. Odstraňte ochranu podložky.|Unten einhängen, schließen und mit M3x10 sichern. Heizbettschutz entfernen.',[858],{action:'cover-in'}),
 step('トップカバーを戻す|Refit the top cover|Nasazení horního krytu|Obere Abdeckung montieren','後ろ右と前の切り欠きを合わせ、指定の2か所をナイロンリベットで固定します。|Align rear-right and front recesses; secure the two specified rivet positions.|Zarovnejte pravý zadní roh a přední výřezy; upevněte dva určené nýty.|Hinten rechts und an den vorderen Aussparungen ausrichten; an den zwei vorgesehenen Nietenstellen sichern.',['top'],{action:'top-in'}),
 step('電源を戻す|Restore power|Zapnutí napájení|Stromversorgung wiederherstellen','ドアを閉じ、電源コードを接続して起動します。|Close the door, reconnect power and switch on.|Zavřete dveře, připojte napájení a zapněte tiskárnu.|Tür schließen, Netzstecker anschließen und einschalten.',['lcd']),
 step('ノズル設定を合わせる|Update nozzle settings|Nastavení trysky|Düseneinstellungen anpassen','径・種類を変えた場合はPrintheadの設定を更新し、ソックの有無も合わせます。径やHF・標準流量を変更した場合は、PrusaSlicerのプリンタープロファイルも実際のノズルに合わせてから印刷を再開します。「画面操作」で実機のファームウェア版に合う経路を確認できます。|If changed, update the Printhead settings for diameter, type and sock. Before printing again, also match the PrusaSlicer printer profile to the actual nozzle diameter and high-flow or standard-flow type. Printer menus shows the route for the firmware on your printer.|Při změně upravte průměr, typ a návlek v nastavení Printhead. Před dalším tiskem také nastavte profil tiskárny v PrusaSliceru podle skutečného průměru a vysokoprůtokové nebo standardní trysky. V nabídce Menu tiskárny vyberte verzi firmwaru své tiskárny.|Bei Änderungen Durchmesser, Typ und Socke unter Printhead anpassen. Vor dem nächsten Druck auch das PrusaSlicer-Druckerprofil an den tatsächlichen Düsendurchmesser und High-Flow- oder Standardtyp anpassen. Unter Druckermenüs den Pfad für die Firmware des Druckers wählen.',['lcd'],{firmwareActions:["printhead"]}),
 step('加熱を確認する|Verify heating|Ověření ohřevu|Aufheizen prüfen','Control → Temperature → Nozzle Temperatureを200 °C超に設定し、ホーム画面の下部で温度が上がることを確認します。温度が上がらない場合やエラーが出る場合は使用を再開せず、冷却・電源切断後に接続を再確認します。|Set Control → Temperature → Nozzle Temperature above 200 °C. Return to the home screen and check the rising temperature in the bottom bar. If it does not rise or an error appears, do not resume use; cool down and unplug before rechecking connections.|V Control → Temperature → Nozzle Temperature nastavte přes 200 °C. Na hlavní obrazovce ověřte růst teploty ve spodní liště. Pokud neroste nebo se objeví chyba, tisk neobnovujte; před kontrolou spojů nechte vychladnout a odpojte napájení.|Control → Temperature → Nozzle Temperature auf über 200 °C stellen. Auf der Startseite den Temperaturanstieg in der unteren Leiste prüfen. Bei fehlendem Anstieg oder Fehler nicht weiterdrucken; vor der Anschlussprüfung abkühlen lassen und Netzstecker ziehen.',['lcd','hotend'],{firmwareActions:["heat"]})
];
const nozzleMiddle=[
 step('Prusa Nozzleを外す|Remove the Prusa Nozzle|Vyjmutí Prusa Nozzle|Prusa Nozzle entfernen','ソックを外し、13–16レンチでブロックを支えます。7 mmの切り欠きでノズルを緩め、抜きます。|Remove the sock. Hold the block with 13–16; use the 7 mm wrench opening to unscrew the nozzle.|Sejměte návlek. Blok držte klíčem 13–16; trysku vyšroubujte 7mm výřezem.|Socke abnehmen. Block mit 13–16 halten; Düse mit der 7-mm-Öffnung herausschrauben.',['hotend'],{action:'nozzle-out'}),
 step('新しいノズルを用意する|Prepare the new nozzle|Příprava nové trysky|Neue Düse bereitlegen','ノズルの種類と径を確認します。|Check nozzle type and diameter.|Zkontrolujte typ a průměr trysky.|Düsentyp und Durchmesser prüfen.',['hotend']),
 step('ノズルを取り付ける|Install the nozzle|Montáž trysky|Düse einsetzen','ブロックに当たるまでねじ込み、支えたまま1.5 Nmで締めます。必要ならソックを戻します。|Seat against the block; support it and tighten to 1.5 Nm. Refit the sock if used.|Zašroubujte k bloku; podepřete jej a dotáhněte na 1,5 Nm. Případně vraťte návlek.|Bis an den Block einschrauben; halten und mit 1,5 Nm anziehen. Socke bei Bedarf montieren.',['hotend'],{action:'nozzle-in'})
];
for(const [id,mid,pages]of [['hotend',[],[4,5,5,6,6,7,7,8,8,9,10,11,12,12,13,14,14,15,16]],['nozzle',nozzleMiddle,[4,5,6,6,7,8,9,9,10,10,11,11,12,13,14,15,15,16,17,17,18,19]]]){
 const steps=structuredClone([...common,...mid,...tail]);if(id==='nozzle'){steps[0].body=l('ホットエンド一式を取り外してからノズルを交換する通常手順です。本体に残したまま交換する場合は、公式の交換治具を使う方法を選びます。標準Nextruder用です。|This standard method removes the hotend before changing the nozzle. To leave the heater block in the printer, use the official replacement-tool method. For the standard Nextruder.|Běžný postup vyjme hotend před výměnou trysky. Pro ponechání topného bloku v tiskárně použijte oficiální přípravek. Pro standardní Nextruder.|Bei diesem Standardverfahren wird zuerst das Hotend ausgebaut. Für den Wechsel im Drucker das offizielle Wechselwerkzeug verwenden. Für den Standard-Nextruder.');steps[0].supplementalSources=[{label:l('公式のノズル交換治具と手順|Official nozzle tool and instructions|Oficiální přípravek a návod|Offizielles Wechselwerkzeug und Anleitung'),url:'https://www.printables.com/model/1237212-core-one-l-nozzle-replacement-tool'}];steps[14].body=l('奥まで挿入した状態を公式の接写写真と照合します。このノズル交換ガイドでは、銅色のリングがごくわずかに見える状態を示しています。押し上げながらつまみネジを締めます。|Match full insertion to the official close-up. This nozzle-replacement guide shows the copper ring just barely visible. Hold the hotend upward while tightening the thumbscrews.|Úplné zasunutí porovnejte s oficiálním detailem. Tento návod ukazuje měděný kroužek jen nepatrně viditelný. Při dotahování ručních šroubů tlačte hotend nahoru.|Vollständiges Einschieben mit dem offiziellen Detailfoto vergleichen. Diese Anleitung zeigt den Kupferring gerade noch sichtbar. Hotend beim Festziehen der Rändelschrauben hochdrücken.');}
 if(id==='hotend'){
  steps[0].body=l('標準Nextruderのホットエンド一式を交換します。ノズルだけを交換する場合は「Prusa Nozzleを交換する」を選びます。この手順ではノズルをヒーターブロックから外しません。HT Hotend・V6アダプターは専用ガイドを使います。|Replace the complete standard Nextruder hotend assembly. To replace only the nozzle, choose Replace the Prusa Nozzle. This procedure keeps the nozzle in the heater block. Use dedicated guides for HT Hotend or V6 adapters.|Vyměňte celý standardní hotend Nextruder. Pro samotnou trysku zvolte Výměna Prusa Nozzle. Zde se tryska z topného bloku nevyšroubovává. Pro HT Hotend nebo adaptér V6 použijte jejich návody.|Die komplette Standard-Nextruder-Hotend-Baugruppe austauschen. Für die einzelne Düse Prusa Nozzle austauschen wählen. Bei diesem Verfahren bleibt die Düse im Heizblock. Für HT Hotend oder V6-Adapter die jeweilige Anleitung verwenden.');
  steps[1].body=l('六角レンチ2.5 mmと、初期型カバー用のT10を用意します。ホットエンド一式の交換では、ノズルを緩めるレンチは使いません。|Prepare a 2.5 mm hex key and T10 for early covers. Complete hotend replacement does not require nozzle-removal wrenches.|Připravte 2,5mm imbus a T10 pro rané kryty. Výměna celého hotendu nevyžaduje klíče pro vyšroubování trysky.|2,5-mm-Innensechskant und T10 für frühe Abdeckungen bereitlegen. Für den kompletten Hotendwechsel werden keine Schlüssel zum Lösen der Düse benötigt.');
 }
 const seating=steps[id==='nozzle'?14:11];
 seating.body=id==='nozzle'?l('ノズルを奥まで差し込みます。銅色のリングは接写写真のようにごくわずかに見える状態です。位置を直す場合は、つまみネジを緩めて差し込み直します。ホットエンドを上へ支えたまま、両方のつまみネジを締めてください。|Insert the nozzle fully. The copper ring should be just barely visible, as in the close-up. If adjustment is needed, loosen the thumbscrews and reseat the nozzle. Hold the hotend upward while tightening both thumbscrews.|Zasuňte trysku nadoraz. Měděný kroužek má být jen nepatrně viditelný, jako na detailní fotografii. Pokud je třeba polohu upravit, povolte ruční šrouby a trysku znovu usaďte. Při utahování obou šroubů tlačte hotend nahoru.|Die Düse ganz einschieben. Der Kupferring sollte wie auf dem Detailfoto gerade noch sichtbar sein. Falls eine Korrektur nötig ist, die Rändelschrauben lösen und die Düse neu einsetzen. Beim Anziehen beider Schrauben das Hotend nach oben drücken.'):l('ノズルを奥まで差し込み、銅色のリングが隠れた状態になっていることを確認します。位置を直す場合は、つまみネジを緩めて差し込み直します。ホットエンドを上へ支えたまま、両方のつまみネジを締めてください。|Insert the nozzle fully and check that the copper ring is concealed. If adjustment is needed, loosen the thumbscrews and reseat the nozzle. Hold the hotend upward while tightening both thumbscrews.|Zasuňte trysku nadoraz a ověřte, že je měděný kroužek skrytý. Pokud je třeba polohu upravit, povolte ruční šrouby a trysku znovu usaďte. Při utahování obou šroubů tlačte hotend nahoru.|Die Düse ganz einschieben und prüfen, dass der Kupferring verdeckt ist. Falls eine Korrektur nötig ist, die Rändelschrauben lösen und die Düse neu einsetzen. Beim Anziehen beider Schrauben das Hotend nach oben drücken.');
 seating.supplementalSources=[{label:l('挿入位置の接写（この交換手順）|Seating close-up for this procedure|Detail usazení pro tento postup|Detailfoto zum Sitz für dieses Verfahren'),url:SERVICE_SOURCES[id]+'#'+(id==='nozzle'?'827252':'826412')}];
 steps.forEach((s,i)=>{s.number=i+1;s.page=pages[i];});
 SERVICE_TASKS.push({id,revision:id==='nozzle'?6:5,title:l(id==='hotend'?'ホットエンドを交換する|Replace the hotend|Výměna hotendu|Hotend austauschen':'Prusa Nozzleを交換する|Replace the Prusa Nozzle|Výměna Prusa Nozzle|Prusa Nozzle austauschen'),category:1,interval:l('交換が必要なとき|When replacement is needed|Při potřebě výměny|Bei erforderlichem Austausch'),source:SERVICE_SOURCES[id],pdf:`https://help.prusa3d.com/wp-content/uploads/generated/printer-maintenance_247_guide_${id==='hotend'?'385707':'821168'}_en_2026-05-13.pdf`,steps});
}
