const clone=s=>structuredClone(s),copy=i=>clone(common[i]),back=i=>clone(tail[i]);
const fanTools=step('工具を用意する|Prepare tools|Příprava nástrojů|Werkzeuge bereitlegen','六角レンチ2.5 mmを用意します。初期仕様のカバーにはT10も使います。|Prepare a 2.5 mm hex key; early covers also need T10.|Připravte 2,5mm imbus; rané kryty vyžadují také T10.|2,5-mm-Innensechskant bereitlegen; frühe Abdeckungen benötigen auch T10.',[858]);
const fanDisconnect=step('ファンのコネクターを抜く|Disconnect the fans|Odpojení ventilátorů|Lüfter abstecken','ラッチを押してプリントファンを抜き、ケーブルを後ろへよけます。次にホットエンドファンを抜きます。|Release the latches. Unplug the print fan and move its lead back; unplug the hotend fan.|Stiskněte západky. Odpojte tiskový ventilátor, kabel odsuňte dozadu a odpojte ventilátor hotendu.|Verriegelungen lösen. Drucklüfter abstecken und Kabel zurücklegen; Hotend-Lüfter abstecken.',['servicePrintLead','serviceHotendFanLead','loveBoard'],{action:'fans-unplug'});
const hotFanOut=step('ホットエンドファンを外す|Remove the hotend fan|Sejmutí ventilátoru hotendu|Hotend-Lüfter ausbauen','ファンを支え、M3x18を2本外してからファンを取り外します。|Support the fan. Remove both M3x18 screws, then the fan.|Ventilátor podepřete. Vyjměte oba M3x18 a pak ventilátor.|Lüfter halten. Beide M3x18 lösen, dann den Lüfter abnehmen.',[791,819,821,'serviceHotendFanLead'],{action:'hotfan-out'});
const hotFanPrepare=step('交換するファンを確認する|Check the replacement fan|Kontrola nového ventilátoru|Ersatzlüfter prüfen','コネクターとケーブルの損傷を確認します。|Check the connector and cable for damage.|Zkontrolujte konektor a kabel, zda nejsou poškozené.|Stecker und Kabel auf Schäden prüfen.',[791,'serviceHotendFanLead']);
const hotFanIn=step('ホットエンドファンを取り付ける|Install the hotend fan|Montáž ventilátoru hotendu|Hotend-Lüfter einbauen','銀色ラベルをヒートシンク側、ケーブルを左へ向け、M3x18を2本で固定します。|Face the silver label toward the heatsink and lead to the left. Secure with both M3x18.|Stříbrný štítek směřuje k chladiči a kabel doleva. Upevněte oběma M3x18.|Silbernes Etikett zum Kühlkörper, Kabel nach links. Mit beiden M3x18 befestigen.',[791,819,821,'serviceHotendFanLead'],{action:'hotfan-in'});
const hotFanPlug=step('ホットエンドファンを接続する|Connect the hotend fan|Připojení ventilátoru hotendu|Hotend-Lüfter anschließen','ケーブルを前から回し、LoveBoard左側の一番下へ接続します。|Route from the front to LoveBoard’s lowest left socket.|Kabel veďte zepředu do nejnižšího levého konektoru LoveBoard.|Kabel von vorne zur untersten linken Buchse des LoveBoard führen.',['serviceHotendFanLead','loveBoard'],{action:'hotfan-plug'});
const printFanPlug=step('プリントファンを接続する|Connect the print fan|Připojení tiskového ventilátoru|Drucklüfter anschließen','溝に沿わせ、配線スペースに小さなループを作ります。LoveBoard左側の中央へ接続します。|Follow the groove, form a small loop in the cable space and plug into the middle left socket.|Veďte drážkou, v prostoru kabelů vytvořte malou smyčku a připojte do prostředního levého konektoru.|Der Nut folgen, kleine Schlaufe im Kabelraum bilden und an der mittleren linken Buchse anschließen.',['servicePrintLead','loveBoard',857],{action:'printfan-plug'});
const fanTest=step('ファンをテストする|Test the fan|Test ventilátoru|Lüfter testen','Control → Calibrations & Tests → Fan testを実行します。|Run Control → Calibrations & Tests → Fan test.|Spusťte Control → Calibrations & Tests → Fan test.|Control → Calibrations & Tests → Fan test ausführen.',['lcd',834],{firmwareActions:["fans"]});
const selftest=step('セルフテストを実行する|Run the selftest|Spuštění selftestu|Selbsttest ausführen','Control → Calibrations & TestsでSelftestを実行します。画面の案内に従い、すべてのテストに緑のチェックが付いてから使用を再開します。|Run Selftest in Control → Calibrations & Tests. Follow the display and resume use after all tests show green check marks.|Spusťte Selftest v Control → Calibrations & Tests. Řiďte se displejem a tiskárnu používejte až po zeleném potvrzení všech testů.|Selftest unter Control → Calibrations & Tests starten. Der Anzeige folgen und erst weiterdrucken, wenn alle Tests grüne Häkchen zeigen.',['lcd',791],{firmwareActions:["selftest"]});
