const clogSource='https://help.prusa3d.com/article/clogged-nozzle-core-one-core-one-l-xl-mk4-s-mk3-9-s_411823';
export const CLOG_SYMPTOMS=[
 {id:'all',title:l('順に確認する|Check the full path|Zkontrolovat celou cestu|Gesamten Weg prüfen'),indices:[0,1,2,3,4]},
 {id:'loading',title:l('フィラメントが入らない|Filament will not load|Filament nelze zavést|Filament lässt sich nicht laden'),indices:[0,1,2]},
 {id:'clicking',title:l('ギアがカチカチ鳴る|Extruder clicks|Extruder cvaká|Extruder klickt'),indices:[2,3,4]},
 {id:'flow',title:l('吐出が細い・途切れる|Weak or interrupted extrusion|Slabá či přerušovaná extruze|Schwache oder unterbrochene Extrusion'),indices:[2,3,4]},
 {id:'obstruction',title:l('Loading obstruction #31119|Loading obstruction #31119|Loading obstruction #31119|Loading obstruction #31119'),indices:[1]}
];
SERVICE_TASKS.push({id:'clog',revision:2,category:2,title:l('詰まりの確認|Check for a blockage|Kontrola ucpání|Auf Blockierung prüfen'),interval:l('症状から確認する|Inspect by symptom|Kontrola podle příznaku|Nach Symptom prüfen'),source:clogSource,steps:[
 step('側面の入口と供給側|Side inlet and filament supply|Boční vstup a přívod filamentu|Seitlicher Eingang und Filamentzufuhr','スプールの絡まり、入口の引っ掛かり、折れた先端を確認します。入口からスプールまで順に確認します。|Check for a tangled spool, a snag at the inlet or a broken tip. Inspect this supply section separately.|Zkontrolujte zamotanou cívku, zachycení ve vstupu a ulomenou špičku. Tuto přívodní část kontrolujte samostatně.|Auf verwickelte Spule, Haken am Eingang oder abgebrochene Spitze prüfen. Diesen Zuführungsabschnitt gesondert prüfen.',['sensorBody','sensorCover','sensorLever'],{camera:'sensor-mount-perspective',source:'https://help.prusa3d.com/article/stuck-filament-detection-31101-core-one-35101-core-one-l-26101-mk4s-13101-mk4-27101-mk3-9s-21101-mk3-9-17108-xl_690089'}),
 step('Nextruderの入口|Nextruder inlet|Vstup Nextruderu|Nextruder-Eingang','① Nextruderのアイドラーを開き、フィラメントセンサーの通路に残片がないか確認します。② 残片を手で取り除きます。必要ならラジオペンチやピンセットを使い、内部を傷つけないようにしてください。③ 通路に残片や汚れがないことを確認し、アイドラーを閉じてロードを試します。④ #31119が続く場合は、画面のInfo → Sensor Infoでセンサーの状態を確認します。|1. Open the Nextruder idler and inspect the filament sensor path for remnants. 2. Remove the remnants manually; use needle-nose pliers or tweezers if needed without scratching internal parts. 3. Check that the path is clear, close the idler and retry loading. 4. If #31119 persists, check the sensor in Info → Sensor Info on the printer.|1. Otevřete idler Nextruderu a zkontrolujte zbytky filamentu v dráze senzoru. 2. Zbytky ručně odstraňte; podle potřeby použijte špičaté kleště nebo pinzetu, ale nepoškrábejte vnitřní díly. 3. Ověřte čistou dráhu, zavřete idler a zkuste zavedení. 4. Pokud #31119 přetrvává, zkontrolujte senzor v Info → Sensor Info na tiskárně.|1. Nextruder-Idler öffnen und den Filamentsensorweg auf Reste prüfen. 2. Reste von Hand entfernen; bei Bedarf Spitzzange oder Pinzette verwenden, ohne innere Teile zu zerkratzen. 3. Freien Kanal prüfen, Idler schließen und erneut laden. 4. Bleibt #31119 bestehen, den Sensor am Drucker unter Info → Sensor Info prüfen.',[817],{camera:'hotend-perspective',source:'https://help.prusa3d.com/article/loading-obstruction-31119-core-one-35119-core-one-l-17119-xl_916795'}),
 step('送りギアとアイドラー|Drive gear and idler|Podávací kolo a idler|Antriebsrad und Idler','フィラメントがギアを越えて進むか、削れた粉や欠片がないか確認します。清掃時に送りギアやアイドラーベアリングへ注油しません。|Check whether filament passes the gear and look for ground filament or fragments. Do not lubricate the drive gear or idler bearings.|Ověřte průchod filamentu za kolo a hledejte obroušený filament či úlomky. Podávací kolo ani ložiska idleru nemažte.|Prüfen, ob Filament das Rad passiert; auf Abrieb und Bruchstücke achten. Antriebsrad und Idlerlager nicht schmieren.',['pgAssembly','idlerBearing1','idlerBearing2'],{camera:'hotend-perspective',source:SERVICE_SOURCES.regular}),
 step('ホットエンド上流|Upper hotend path|Horní část cesty hotendu|Oberer Hotend-Kanal','ギアの先へ進んでも吐出しない場合は、ノズル先端より上流も確認します。外す前にアンロードと冷却の手順を確認してください。|If filament passes the gear but does not extrude, also inspect upstream of the tip. Review unloading and cooling before removal.|Pokud filament projde kolem, ale nevytlačuje se, zkontrolujte také cestu nad špičkou. Před demontáží ověřte vysunutí a chlazení.|Passiert das Filament das Rad ohne Extrusion, auch oberhalb der Spitze prüfen. Vor dem Ausbau Entladen und Abkühlen nachlesen.',['regionTube','regionHeatbreak'],{camera:'hotend-perspective'}),
 step('ノズル先端|Nozzle tip|Špička trysky|Düsenspitze','吐出の途切れ、先端への巻き付きや付着を確認します。清掃・コールドプル・交換の選択は、ノズルの種類に合う公式説明で確認してください。|Look for interrupted flow, curling or plastic sticking to the tip. Use the official instructions to choose cleaning, cold pull or replacement for your nozzle.|Sledujte přerušovaný tok, stáčení či ulpívání plastu na špičce. Čištění, cold pull nebo výměnu volte podle oficiálního návodu pro danou trysku.|Auf unterbrochenen Fluss, Kringeln oder anhaftenden Kunststoff achten. Reinigung, Cold Pull oder Austausch nach der Anleitung für die jeweilige Düse wählen.',['regionTip'],{camera:'hotend-perspective'})
]});

