for(const sock of [true,false]){
 const id=sock?'nozzle-tool':'nozzle-tool-bare',tool=sock?'nozzleToolSock':'nozzleToolBare';
 const steps=[
  step('治具を使う交換方法を確認する|Review the printed-tool method|Postup s tištěným přípravkem|Wechsel mit gedrucktem Werkzeug prüfen','公式の治具でヒーターブロックを支え、本体に残したままPrusa Nozzleだけを交換します。ヒーターとサーミスターの配線は抜きません。ノズルを保持するのは側面のつまみネジ2本です。ブロック側のヒーター・センサー固定ネジはこの作業では緩めません。別の方法は下の関連作業から選べます。|The official tool supports the heater block in the printer while only the Prusa Nozzle is changed. Leave heater and thermistor leads connected. Two side thumbscrews retain the nozzle; do not loosen heater or sensor grub screws in the block. Choose another method under Related tasks.|Oficiální přípravek podpírá topný blok v tiskárně při výměně samotné Prusa Nozzle. Kabely topení a termistoru zůstávají připojené. Trysku drží dva boční ruční šrouby; stavěcí šrouby topení a senzoru v bloku nepovolujte. Jiný postup zvolte v souvisejících úkonech.|Das offizielle Werkzeug hält den Heizblock im Drucker beim Wechsel der einzelnen Prusa Nozzle. Heizungs- und Thermistorleitungen bleiben angeschlossen. Zwei seitliche Rändelschrauben halten die Düse; die Madenschrauben für Heizung und Sensor im Block nicht lösen. Andere Verfahren unter Verwandte Aufgaben wählen.',['hotend',795,807],{related:['nozzle','hotend',sock?'nozzle-tool-bare':'nozzle-tool']}),
  step('正しい治具と工具を用意する|Prepare the matching tool|Správný přípravek a nástroje|Passendes Werkzeug bereitlegen',sock?'ソックあり用の「CORE One sock」を用意します。ソックなしの場合は「治具・ソックなし」の作業へ切り替えます。公式の印刷設定は0.20 mm STRUCTURAL、外周2本、Grid 15%、材料はPETGまたはPC Blend Carbon Fiberです。7 mmソケットかユニバーサルレンチも用意します。HT Hotend・V6アダプターにはこの手順を使いません。|Use CORE One sock with the silicone sock fitted. For a bare block, select the no-sock task. Official print settings: 0.20 mm STRUCTURAL, 2 perimeters, 15% Grid, PETG or PC Blend Carbon Fiber. Prepare a 7 mm socket or universal wrench. This procedure excludes HT Hotend and V6 adapters.|S nasazeným návlekem použijte CORE One sock. Pro holý blok zvolte úkon bez návleku. Oficiální tisk: 0,20 mm STRUCTURAL, 2 perimetry, 15 % Grid, PETG nebo PC Blend Carbon Fiber. Připravte 7mm nástrčný nebo univerzální klíč. Postup není pro HT Hotend a V6.|Mit montierter Silikonsocke CORE One sock verwenden. Für den blanken Block den Vorgang ohne Socke wählen. Offizieller Druck: 0,20 mm STRUCTURAL, 2 Perimeter, 15 % Grid, PETG oder PC Blend Carbon Fiber. 7-mm-Steck- oder Universalschlüssel bereitlegen. Nicht für HT Hotend oder V6.':'ソックなし用の「CORE One no sock」を用意します。ソックを付けている場合は「治具・ソックあり」の作業へ切り替えます。公式の印刷設定は0.20 mm STRUCTURAL、外周2本、Grid 15%、材料はPETGまたはPC Blend Carbon Fiberです。7 mmソケットかユニバーサルレンチも用意します。HT Hotend・V6アダプターにはこの手順を使いません。|Use CORE One no sock with the bare heater block. If a silicone sock is fitted, select the sock task. Official print settings: 0.20 mm STRUCTURAL, 2 perimeters, 15% Grid, PETG or PC Blend Carbon Fiber. Prepare a 7 mm socket or universal wrench. This procedure excludes HT Hotend and V6 adapters.|Pro holý topný blok použijte CORE One no sock. S nasazeným návlekem zvolte úkon s návlekem. Oficiální tisk: 0,20 mm STRUCTURAL, 2 perimetry, 15 % Grid, PETG nebo PC Blend Carbon Fiber. Připravte 7mm nástrčný nebo univerzální klíč. Postup není pro HT Hotend a V6.|Am blanken Heizblock CORE One no sock verwenden. Mit Silikonsocke den Vorgang mit Socke wählen. Offizieller Druck: 0,20 mm STRUCTURAL, 2 Perimeter, 15 % Grid, PETG oder PC Blend Carbon Fiber. 7-mm-Steck- oder Universalschlüssel bereitlegen. Nicht für HT Hotend oder V6.',['hotend'],{sourcePhotos:toolPhotos,related:[sock?'nozzle-tool-bare':'nozzle-tool']}),
  clone(common[2]),
  step('ブロックの汚れと冷却を確認する|Check cleanliness and cooling|Čistota a vychladnutí bloku|Sauberkeit und Abkühlung prüfen','ヒーターブロックの付着物を確認します。汚れがある場合は「ノズル外側の清掃」を先に行い、再び完全に室温まで冷ましてから戻ります。耐熱材料で作った治具でも、高温のホットエンドには装着しません。|Check the heater block for residue. If dirty, complete Clean the nozzle exterior first, then let it cool fully to ambient before returning. Even a heat-resistant printed tool must not be installed on a hot hotend.|Zkontrolujte usazeniny na topném bloku. Je-li znečištěný, nejprve vyčistěte vnějšek trysky a pak nechte zcela vychladnout na pokojovou teplotu. Ani tepelně odolný přípravek nenasazujte na horký hotend.|Heizblock auf Rückstände prüfen. Bei Verschmutzung zuerst Düsenaußenseite reinigen und danach vollständig auf Raumtemperatur abkühlen lassen. Auch hitzebeständige gedruckte Werkzeuge nicht an einem heißen Hotend montieren.',['hotend'],{related:['hotend-clean']}),
  clone(common[3]),clone(common[5]),
  step('治具をブロックに装着する|Fit the tool to the block|Nasazení přípravku na blok|Werkzeug am Block anbringen','ソック有無に合う治具をヒーターブロックに合わせ、無理な力を掛けずに滑り込ませて支えます。配線を引っ張らず、ねじりません。3Dの治具は位置関係を示す模式図です。実物は公式データから用意してください。|Align the matching sock or no-sock tool with the heater block and gently slide it into place to support it. Do not pull or twist the wires. The 3D tool is an illustration of its position; prepare the real tool from the official files.|Odpovídající přípravek s návlekem či bez něj srovnejte s blokem a jemně nasuňte, aby jej podpíral. Za vodiče netahejte ani je nekruťte. 3D přípravek je schéma polohy; skutečný vytiskněte z oficiálních dat.|Passendes Werkzeug für den Block mit oder ohne Socke ausrichten und vorsichtig zur Abstützung aufschieben. Leitungen nicht ziehen oder verdrehen. Das 3D-Werkzeug zeigt die Lage schematisch; das echte Werkzeug aus den offiziellen Dateien herstellen.',[tool,'hotend'],{action:'tool-in',sourcePhotos:toolPhotos}),
  step('つまみネジ2本を緩める|Loosen both thumbscrews|Povolení obou ručních šroubů|Beide Rändelschrauben lösen','治具でブロックを支えたまま、Nextruder側面のつまみネジ2本を数回転緩めます。完全には抜きません。ノズルを回す前に両方が緩んでいることを確認します。|Keep the block supported by the tool. Loosen both Nextruder side thumbscrews a few turns without removing them. Check both are loose before rotating the nozzle.|Blok ponechte podepřený přípravkem. Oba boční ruční šrouby povolte o několik otáček, nevyjímejte je. Před otáčením trysky ověřte povolení obou.|Block weiter mit dem Werkzeug abstützen. Beide seitlichen Rändelschrauben am Nextruder einige Umdrehungen lösen, nicht entfernen. Vor dem Drehen der Düse beide prüfen.',[795,807,'hotend',tool],{action:'tool-release'}),
  step('ノズルを緩めて抜く|Unscrew and withdraw the nozzle|Vyšroubování a vytažení trysky|Düse lösen und herausziehen','室温のまま、治具がブロックを支えていることを確かめます。7 mmソケットかユニバーサルレンチでノズルを緩め、手でねじを外してチューブが抜けるまでまっすぐ下げます。チューブを横に曲げず、ブロックを配線だけでつり下げません。|At ambient temperature, check the tool supports the block. Loosen the nozzle with a 7 mm socket or universal wrench, unscrew by hand and withdraw straight down until the tube clears. Do not bend the tube sideways or leave the block hanging from its wires.|Při pokojové teplotě ověřte podepření bloku. Trysku povolte 7mm nástrčným či univerzálním klíčem, rukou vyšroubujte a vytáhněte přímo dolů až do uvolnění trubičky. Trubičku neohýbejte do strany; blok nesmí viset na vodičích.|Bei Raumtemperatur die Abstützung prüfen. Düse mit 7-mm-Steck- oder Universalschlüssel lösen, von Hand herausschrauben und gerade nach unten ziehen, bis das Rohr frei ist. Rohr nicht seitlich biegen und Block nicht an den Leitungen hängen lassen.',['serviceNozzle',tool],{action:'tool-nozzle-out'}),
  step('交換するノズルを確認する|Check the replacement nozzle|Kontrola nové trysky|Ersatzdüse prüfen','交換するPrusa Nozzleの種類と径を確認します。ヒーターブロック、ヒーター、サーミスター、ソックの有無はこの方法では変えません。治具でブロックを支えた状態を保ちます。|Check the replacement Prusa Nozzle type and diameter. This method keeps the block, heater, thermistor and sock configuration unchanged. Keep the block supported by the tool.|Ověřte typ a průměr nové Prusa Nozzle. Blok, topení, termistor a stav návleku se tímto postupem nemění. Blok stále podpírejte přípravkem.|Typ und Durchmesser der neuen Prusa Nozzle prüfen. Block, Heizung, Thermistor und Sockenzustand bleiben bei diesem Verfahren erhalten. Block weiter abstützen.',['serviceNozzle',tool]),
  step('新しいノズルを取り付ける|Install the new nozzle|Montáž nové trysky|Neue Düse einsetzen','チューブをまっすぐ差し込み、ノズルがブロックの面に当たるまで手でねじ込みます。治具でブロックを支えたまま締めます。Prusa Nozzle取付ガイドの指定は1.5 Nmで、トルクレンチが推奨されています。過大な力を掛けません。|Insert the tube straight and screw in by hand until the nozzle meets the block surface. Tighten with the block supported by the tool. The Prusa Nozzle installation guide specifies 1.5 Nm and recommends a torque wrench. Do not apply excessive force.|Trubičku zasuňte rovně a rukou zašroubujte, až tryska dosedne na plochu bloku. Dotáhněte s podepřeným blokem. Montážní návod Prusa Nozzle uvádí 1,5 Nm a doporučuje momentový klíč. Nepoužívejte nadměrnou sílu.|Rohr gerade einsetzen und von Hand einschrauben, bis die Düse an der Blockfläche anliegt. Bei abgestütztem Block festziehen. Die Prusa-Nozzle-Montageanleitung nennt 1,5 Nm und empfiehlt einen Drehmomentschlüssel. Keine übermäßige Kraft anwenden.',['serviceNozzle',tool],{action:'tool-nozzle-in',supplementalSources:[{label:l('ノズル取付の指定トルク|Specified nozzle installation torque|Předepsaný moment trysky|Vorgeschriebenes Düsen-Anzugsmoment'),url:SERVICE_SOURCES.nozzle+'#827672'}]}),
  clone(SERVICE_TASKS.find(t=>t.id==='nozzle').steps[14]),
  step('つまみネジ2本を手で締める|Hand-tighten both thumbscrews|Ruční dotažení obou šroubů|Beide Rändelschrauben von Hand anziehen','ホットエンドを上へ支えたまま、側面のつまみネジ2本を手で締めます。つまみネジに工具は使いません。冷えた状態で左右に軽く動かし、ホットエンドが動かないことを確認します。|Hold the hotend upward and hand-tighten both side thumbscrews. Do not use tools on them. While cold, gently check side-to-side that the hotend does not move.|Hotend tlačte vzhůru a oba boční ruční šrouby utáhněte rukou, bez nástrojů. Za studena jemným pohybem do stran ověřte, že se hotend nehýbe.|Hotend nach oben halten und beide seitlichen Rändelschrauben von Hand anziehen. Keine Werkzeuge verwenden. Im kalten Zustand vorsichtig seitlich prüfen, dass sich das Hotend nicht bewegt.',['hotend',795,807,tool],{action:'tool-secure',supplementalSources:[{label:l('つまみネジと固定の確認|Thumbscrew and seating check|Kontrola ručních šroubů a usazení|Rändelschrauben und Sitz prüfen'),url:'https://help.prusa3d.com/article/nozzle-cleaning-failed-31834-core-one-35834-core-one-l-26834-mk4s-13834-mk4-27834-mk3-9s-21834-mk3-9-17834-xl_689429'}]}),
  step('治具と保護材を外す|Remove the tool and bed protection|Sejmutí přípravku a ochrany|Werkzeug und Heizbettschutz entfernen','ノズルが固定されたことを確かめてから、配線を引っ掛けないように治具を外します。ベッドの保護材と工具を本体内から取り出します。治具を付けたまま加熱や印刷を始めません。|After confirming the nozzle is secured, remove the tool without catching any wires. Remove the bed protection and loose tools. Remove the printed tool before heating or printing.|Po ověření upevnění trysky sejměte přípravek bez zachycení vodičů. Vyjměte ochranu podložky a nástroje. Před ohřevem či tiskem musí být tištěný přípravek odstraněn.|Nach Prüfung des festen Sitzes das Werkzeug abnehmen, ohne Leitungen einzuhaken. Heizbettschutz und lose Werkzeuge entfernen. Das gedruckte Werkzeug vor Heizen oder Drucken abnehmen.',[tool,'heatbed'],{action:'tool-out'}),
  clone(tail[7]),clone(tail[8]),clone(tail[9])
 ];
 steps[11].body=l('ホットエンドをヒートシンクの奥まで押し上げます。ノズル交換ガイドの接写では、銅色のリングがごくわずかに見える位置です。つまみネジはまだ緩めたままにし、次の手順で上へ支えながら固定します。|Push the hotend fully into the heatsink. The nozzle-replacement close-up shows the copper ring just barely visible. Leave the thumbscrews loose for now; secure them while supporting upward in the next step.|Hotend zatlačte nadoraz do chladiče. Detail návodu k výměně trysky ukazuje měděný kroužek jen nepatrně viditelný. Ruční šrouby zatím ponechte povolené; v dalším kroku je dotáhnete s tlakem vzhůru.|Hotend vollständig in den Kühlkörper hochdrücken. Das Detailfoto zum Düsenwechsel zeigt den Kupferring gerade noch sichtbar. Rändelschrauben noch locker lassen; im nächsten Schritt bei Druck nach oben befestigen.');
 steps.forEach((s,i)=>{s.number=i+1;delete s.page;s.source??=toolSource;});
 steps[2].source=SERVICE_SOURCES.nozzle+'#826822';steps[4].source=SERVICE_SOURCES.nozzle+'#826876';steps[11].source=SERVICE_SOURCES.nozzle+'#827252';steps[14].source=SERVICE_SOURCES.nozzle+'#827424';steps[15].source=SERVICE_SOURCES.nozzle+'#827460';steps[16].source=SERVICE_SOURCES.nozzle+'#827530';
 SERVICE_TASKS.push({id,revision:2,category:1,nozzleTool:{sock,illustrative:true},title:l(sock?'ソックあり：治具でノズル交換|With sock: tool nozzle swap|S návlekem: výměna trysky přípravkem|Mit Socke: Düsenwechsel mit Werkzeug':'ソックなし：治具でノズル交換|No sock: tool nozzle swap|Bez návleku: výměna trysky přípravkem|Ohne Socke: Düsenwechsel mit Werkzeug'),interval:l('公式治具を用意した場合|With the official printed tool|S oficiálním tištěným přípravkem|Mit dem offiziellen gedruckten Werkzeug'),source:methodSource,steps});
}
for(const id of ['nozzle','hotend'])SERVICE_TASKS.find(t=>t.id===id).steps[0].related=['nozzle-tool','nozzle-tool-bare',id==='nozzle'?'hotend':'nozzle'];
// Register these methods against their existing official overview, so the
// Japanese source library also exposes the new in-app tasks.
