for(const catalog of new Set([OFFICIAL_MAINTENANCE_JA,unversionedMaintenanceCatalog]))catalog.guides.find(g=>g.id==='734706').tasks=['nozzle-tool','nozzle-tool-bare','nozzle','hotend'];

